    {
        ES2PANDA_ASSERT(HasLocation());
        auto loc = Location();
        return {loc->line, loc->col};
    }

    size_t Line() const
    {
        ES2PANDA_ASSERT(HasLocation());
        return Location()->line;
    }

    size_t Offset() const
    {
        ES2PANDA_ASSERT(HasLocation());
        return Location()->col;
    }

